  );
  const cache = this._resolvedPlaneOptions;
  cache.size = fallbackSize;
  cache.width = this._resolvePositiveNumber(plane?.width, fallbackSize);
  cache.height = this._resolvePositiveNumber(plane?.height, CLOUD_PLANE_HEIGHT);
  cache.segments = Math.max(
    1,
    Math.round(
      this._resolvePositiveNumber(plane?.segments, CLOUD_PLANE_SEGMENTS),
    ),
  );
